@app.get(
    "/__COLLECTION__/export"
)
def export_csv(__AUTH_PARAMS__):

    output = io.StringIO(newline='')
    writer = csv.DictWriter(output, fieldnames=sorted({key for item in __VISIBLE_RECORDS__ for key in item}))
    writer.writeheader()
    writer.writerows(__VISIBLE_RECORDS__)
    output.seek(0)
    return StreamingResponse(iter([output.getvalue()]), media_type='text/csv', headers={'Content-Disposition': 'attachment; filename=__COLLECTION__.csv'})
